    [CascadingParameter]
    private Task<AuthenticationState> AuthenticationStateTask { get; set; }
    private bool areVisible = true;

    IEnumerable<ExamResult> Model { get; set; }

    ExamResultWithAnswers questions = null;

    protected override async Task OnInitializedAsync()
    {
        AuthenticationState state = await AuthenticationStateTask;
        Model = await service.GetExamResultsByUsername(state.User.Identity.Name);
    }

    private async Task GetExamResult(DateTime solvedOn, int? examId)
    {
        var authState = await AuthenticationStateTask;
        questions = await service.GetExamResultByExamIdAndUsernameAsync(authState.User.Identity.Name, examId, solvedOn);

        if (!questions.AllCorrect)
        {
            areVisible = false;
        }
    }

    private void Back()
    {
        this.areVisible = true;
    }

